import math

def detect_action_loop(actions: list[dict], dist_threshold: float = 8.0) -> dict:
    n = len(actions)
    for i in range(n - 2):
        a1, a2, a3 = actions[i], actions[i+1], actions[i+2]
        if a1.get("action_type") == a2.get("action_type") == a3.get("action_type") == "click":
            if a1.get("selector") and a1.get("selector") == a2.get("selector") == a3.get("selector"):
                return {"has_loop": True, "loop_start_step": i + 1, "reason": "repeated_selector_click"}
            c1, c2, c3 = a1.get("coords"), a2.get("coords"), a3.get("coords")
            if c1 and c2 and c3:
                d12 = math.hypot(c1[0] - c2[0], c1[1] - c2[1])
                d23 = math.hypot(c2[0] - c3[0], c2[1] - c3[1])
                if d12 <= dist_threshold and d23 <= dist_threshold:
                    return {"has_loop": True, "loop_start_step": i + 1, "reason": "spatial_coordinate_click_loop"}
    for i in range(n - 3):
        window = actions[i:i+4]
        if all(a.get("action_type") == "scroll" for a in window):
            scroll_positions = [a.get("scroll_top") for a in window]
            if scroll_positions[0] is not None and len(set(scroll_positions)) == 1:
                return {"has_loop": True, "loop_start_step": i + 1, "reason": "stagnant_scroll_loop"}
    return {"has_loop": False, "loop_start_step": None, "reason": None}

