gold_code:
import csv
import io

def verify_csv_artifact(csv_text: str, expected_totals: dict[str, float], key_col: str = "invoice_id", val_col: str = "total_due") -> bool:
    if not csv_text or not csv_text.strip():
        return False
    reader = csv.DictReader(io.StringIO(csv_text.strip()))
    if not reader.fieldnames:
        return False
    normalized_rows = {}
    for row in reader:
        clean_row = {k.strip(): (v.strip() if v is not None else "") for k, v in row.items() if k is not None}
        k_val = clean_row.get(key_col)
        if k_val:
            try:
                normalized_rows[k_val] = float(clean_row[val_col])
            except (KeyError, ValueError):
                return False
    if set(normalized_rows.keys()) != set(expected_totals.keys()):
        return False
    for k, exp_v in expected_totals.items():
        if abs(normalized_rows[k] - float(exp_v)) > 1e-2:
            return False
    return True

