from csv_verifier import verify_csv_artifact

def test_csv_verifier_handles_order_and_float_precision():
    csv_content = "invoice_id , vendor , total_due\nINV-904, CloudCorp, 8925.0\nINV-901, TechSupply, 4200.000\n"
    expected = {"INV-901": 4200.00, "INV-904": 8925.00}
    assert verify_csv_artifact(csv_content, expected) is True

def test_csv_verifier_rejects_wrong_amount_with_all_rows_present():
    csv_content = "invoice_id,vendor,total_due\nINV-901,TechSupply,9999.99\nINV-904,CloudCorp,8925.00\n"
    expected = {"INV-901": 4200.00, "INV-904": 8925.00}
    assert verify_csv_artifact(csv_content, expected) is False

