def score_multi_stage_completion(completed_subgoals: list[str], required_subgoals: list[str], committed: bool, require_final_commit: bool = True) -> dict:
    req_set = set(required_subgoals)
    comp_set = set(completed_subgoals)
    matched = len(req_set & comp_set)
    total = len(req_set) + (1 if require_final_commit else 0)
    raw_score = (matched + (1 if (committed and require_final_commit) else 0)) / max(1, total)
    if require_final_commit and not committed:
        capped_score = min(0.5, round(raw_score, 3))
        return {
            "score": capped_score,
            "passed": False,
            "omitted_commit": True,
        }
    all_subgoals_done = matched == len(req_set)
    passed = all_subgoals_done and (committed if require_final_commit else True)
    return {
        "score": round(raw_score, 3),
        "passed": passed,
        "omitted_commit": False,
    }
